/bin/bash -lc "python3 - <<'PY'
import json,tarfile
from pathlib import Path
for fn in ['data.json','benchmark.json']:
 d=json.load(open('intake/'+fn)); print(fn)
 for k,v in d.items():
  print(k, (str(v)[:6000] if len(str(v))<15000 else 'LARGE '+str(type(v))+' '+str(len(v))+' '+str(v)[:1800]))
s=Path('intake/brief.md').read_text(); print('BRIEF after inventory',s[s.rfind('\\n|')+1:]); print('brief sections',[l for l in s.splitlines() if l.startswith('#')])
for archive in ['pinder-source.tar.gz','frodock3_linux64.tgz']:
 with tarfile.open('intake/'+archive) as t:
  print(archive, t.getnames()[:8])
  for m in t:
   if m.isfile() and (m.name.endswith(('run/frodock/predict.py','compile_frodock.sh','pinder-eval/pinder/eval/run.py','pinder-methods/pinder/methods/main.py','pyproject.toml'))):
    b=t.extractfile(m).read().decode(); print('\\nFILE',m.name,'\\n',b[:24000])
PY"

